#include "reshade_input_client.h"
#include <iostream>
#include <thread>
#include <cstdlib>
using namespace ldb_reshade;
static void check(bool b){if(!b){std::cerr<<"Client input test failed error="<<GetLastError()<<"\n";std::exit(2);}}
static SHORT key(int){return 0;}
static BOOL cursor(LPPOINT p){p->x=10;p->y=20;return TRUE;}
static UINT raw(HRAWINPUT,UINT,LPVOID,PUINT,UINT){return UINT(-1);}
int main(){
 const auto name="LDBNativeClientInput-"+std::to_string(GetCurrentProcessId());
 check(Bridge::create(name.c_str(),GetCurrentProcessId()));check(Bridge::open(name.c_str(),GetCurrentProcess()));
 auto* data=Bridge::storage();
 const HWND hwnd=CreateWindowExW(0,L"STATIC",L"LDB input native fixture",WS_OVERLAPPEDWINDOW,0,0,128,128,nullptr,nullptr,GetModuleHandleW(nullptr),nullptr);check(hwnd!=nullptr);
 ShowWindow(hwnd,SW_SHOW);SetForegroundWindow(hwnd);SetFocus(hwnd);
 check(GetAncestor(GetForegroundWindow(),GA_ROOT)==hwnd);
 Client::set(hwnd);const auto epoch=data->epoch.load();
 Client::message(hwnd,WM_KEYDOWN,65,0,false,key,cursor,raw);
 Client::message(hwnd,WM_CHAR,0x4e2d,0,false,key,cursor,raw);
 Client::message(hwnd,WM_MOUSEWHEEL,WPARAM(120)<<16,0,false,key,cursor,raw);
 Client::message(hwnd,WM_KEYUP,65,0,false,key,cursor,raw);
 unsigned events=0;bool sawKey=false,sawRelease=false,sawText=false,sawWheel=false;
 check(consume(*data,epoch,[&](const Event& e){++events;if(e.kind==uint32_t(Kind::Key)&&e.code==65){if(e.flags&Down)sawKey=true;else sawRelease=true;}if(e.kind==uint32_t(Kind::Text)&&e.code==0x4e2d)sawText=true;if(e.kind==uint32_t(Kind::Wheel)&&e.x==120)sawWheel=true;}));
 check(events==5&&sawKey&&sawRelease&&sawText&&sawWheel); // One focus edge plus four input records.
 // Steam suppresses our source focus. Repeated unrelated background messages
 // must not fill the discrete-event ring.
 Client::message(hwnd,WM_ACTIVATEAPP,0,0,true,key,cursor,raw);
 for(unsigned i=0;i<2000;++i)Client::message(hwnd,WM_NULL,0,0,true,key,cursor,raw);
 check(!data->fault.load()&&data->write.load()-data->read.load()==1);
 consume(*data,epoch,[](const Event&){});
 publishCapture(*data,epoch,7,GetTickCount64());
 bool capture=false;unsigned transitions=0;
 auto apply=[&](bool value){if(capture==value)return false;capture=value;++transitions;return true;};
 Client::refresh(false,apply,SetCapture);check(capture&&transitions==1);
 Client::refresh(false,apply,SetCapture);check(transitions==1);
 Client::refresh(true,apply,SetCapture);check(!capture&&transitions==2);
 // Raw keyboard state must survive a stale legacy GetKeyboardState snapshot.
 RAWINPUTDEVICE registration{1,6,RIDEV_NOLEGACY,hwnd};check(RegisterRawInputDevices(&registration,1,sizeof(registration))!=FALSE);Client::set(hwnd);
 RAWINPUT packet{};packet.header.dwType=RIM_TYPEKEYBOARD;packet.header.dwSize=sizeof(packet);packet.data.keyboard.VKey=VK_CONTROL;
 auto rawKeyboard=[&](HRAWINPUT,UINT,LPVOID destination,PUINT bytes,UINT){*static_cast<RAWINPUT*>(destination)=packet;*bytes=sizeof(packet);return static_cast<UINT>(sizeof(packet));};
 Client::message(hwnd,WM_INPUT,RIM_INPUT,0,false,key,cursor,rawKeyboard);
 Client::sample(false,key,cursor,[](PBYTE value){std::fill_n(value,256,BYTE(0));return TRUE;});
 check((data->sourceFlags.load()&Ctrl)!=0);unsigned ctrlDown=0,ctrlUp=0;
 consume(*data,epoch,[&](const Event& e){if(e.kind==uint32_t(Kind::Key)&&e.code==VK_CONTROL){if(e.flags&Down)++ctrlDown;else ++ctrlUp;}});check(ctrlDown==1&&ctrlUp==0);
 packet.data.keyboard.Flags=RI_KEY_BREAK;Client::message(hwnd,WM_INPUT,RIM_INPUT,0,false,key,cursor,rawKeyboard);check(!(data->sourceFlags.load()&Ctrl));consume(*data,epoch,[](const Event&){});
 packet.data.keyboard.Flags=0;packet.data.keyboard.VKey=VK_SHIFT;packet.data.keyboard.MakeCode=0x2a;Client::message(hwnd,WM_INPUT,RIM_INPUT,0,false,key,cursor,rawKeyboard);
 packet.data.keyboard.VKey=65;packet.data.keyboard.MakeCode=0x1e;Client::message(hwnd,WM_INPUT,RIM_INPUT,0,false,key,cursor,rawKeyboard);
 bool uppercase=false;consume(*data,epoch,[&](const Event& e){if(e.kind==uint32_t(Kind::Text)&&e.code==65)uppercase=true;});check(uppercase);
 packet.data.keyboard.Flags=RI_KEY_BREAK;Client::message(hwnd,WM_INPUT,RIM_INPUT,0,false,key,cursor,rawKeyboard);packet.data.keyboard.VKey=VK_SHIFT;packet.data.keyboard.MakeCode=0x2a;Client::message(hwnd,WM_INPUT,RIM_INPUT,0,false,key,cursor,rawKeyboard);consume(*data,epoch,[](const Event&){});
 registration.dwFlags=RIDEV_REMOVE;registration.hwndTarget=nullptr;check(RegisterRawInputDevices(&registration,1,sizeof(registration))!=FALSE);Client::set(hwnd);
 // Focus loss must leave the OS cursor unclipped; never restore game-only
 // clip/cursor state while another application owns the foreground.
 RECT original{};check(GetClipCursor(&original)!=FALSE);
 const RECT gameClip{10,20,80,90};check(ClipCursor(&gameClip)!=FALSE);
 Client::refresh(false,apply,SetCapture);check(capture);
 ShowWindow(hwnd,SW_HIDE);Client::refresh(false,apply,SetCapture);check(!capture);
 RECT after{};check(GetClipCursor(&after)!=FALSE&&!EqualRect(&after,&gameClip));
 ClipCursor(&original);
 // Only the window owner enqueues. Other threads may sample position/focus.
 std::thread other([&]{for(int i=0;i<200;++i)Client::sample(true,key,cursor,[](PBYTE){return FALSE;});});other.join();check(!data->fault.load()&&data->write.load()==data->read.load());
 Client::set(nullptr);check(data->epoch.load()!=epoch&&!Bridge::capture(GetTickCount64()));
 DestroyWindow(hwnd);
 std::cout<<"PASS actual LDB Client collector: original HWND, ordered key/text/wheel, focus edge, no background flood, capture handoff, owner-only enqueue, rebinding\n";
}
